<?php
// Hand-written to match what grpc_php_plugin emits.
//
// The message classes beside this file are generated by protoc from
// proto/health.proto; only the service stub needs the gRPC plugin, which is a
// separate binary that is not part of a normal protoc install. Rather than make
// the build depend on it for fifteen lines of boilerplate, this is that
// boilerplate. Regenerate the messages with scripts/compile-proto.sh; this file
// changes only if grpc.health.v1 does, which it has not since 2017.

namespace Grpc\Health\V1;

/**
 * The standard gRPC health checking service, as served by the PulseIndex engine.
 *
 * Needs no particular scope on the API key, so it works with any key, which is
 * why readiness is read from here.
 */
class HealthClient extends \Grpc\BaseStub
{
    /**
     * @param string $hostname hostname
     * @param array $opts channel options
     * @param \Grpc\Channel $channel (optional) re-use channel object
     */
    public function __construct($hostname, $opts, $channel = null)
    {
        parent::__construct($hostname, $opts, $channel);
    }

    /**
     * Check reports the serving status of one service name.
     *
     * An empty `service` asks for the health of the server as a whole, which is
     * what the health spec defines and what callers should normally use.
     *
     * @param \Grpc\Health\V1\HealthCheckRequest $argument input argument
     * @param array $metadata metadata
     * @param array $options call options
     * @return \Grpc\UnaryCall
     */
    public function Check(
        \Grpc\Health\V1\HealthCheckRequest $argument,
        $metadata = [],
        $options = []
    ) {
        return $this->_simpleRequest(
            '/grpc.health.v1.Health/Check',
            $argument,
            ['\Grpc\Health\V1\HealthCheckResponse', 'decode'],
            $metadata,
            $options
        );
    }
}
